<?php require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../services/userService.php';require_once __DIR__.'/../includes/auth.php';$pdo=openDatabase();$user=requireLogin($pdo);$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrfToken($_POST);try{changeOwnPassword($pdo,(int)$user['user_id'],$_POST);$message='Password updated.';}catch(InvalidArgumentException $e){$error=$e->getMessage();}}require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/nav.php';?><main class="container py-4"><h1>Change password</h1><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if(!empty($message)):?><div class="alert alert-success"><?=$message?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><label>Current password<input class="form-control" type="password" name="current_password" required></label><label>New password<input class="form-control" type="password" name="new_password" minlength="10" required></label><label>Confirm new password<input class="form-control" type="password" name="confirm_password" required></label><button class="btn btn-primary">Update password</button></form></main><?php require __DIR__.'/../includes/footer.php';?>
